on conflict (video_path) do update set scheduled_at = excluded.scheduled_at, status = 'queued', error = null where ig_reels.status in ('queued','draft','failed');
update public.ig_reels t set scheduled_at = v.ts at time zone 'America/New_York', status='queued' from (values
('9fab4b15-72a6-471a-8e61-925760cce1ed'::uuid, timestamp '2026-10-27 15:00'),
('67f78e72-5554-4315-b13d-09ec13ffe121'::uuid, timestamp '2026-10-31 15:00'),
('04c817b6-b680-4779-94c7-ef40defa5b1b'::uuid, timestamp '2026-11-01 11:30'),
('fdbb2dd5-4303-4a15-9cee-64ea3fab3b99'::uuid, timestamp '2026-11-03 15:00'),
('1a24277f-69ac-4cd2-b944-c4a84c1bfd54'::uuid, timestamp '2026-11-06 08:00'),
('7b85d45b-8eab-47ff-8461-168f056c6b39'::uuid, timestamp '2026-11-06 11:30'),
('88e58c51-ca99-4e0e-8b47-41fc097f2b9b'::uuid, timestamp '2026-11-08 08:00'),
('24699e3e-565e-4ddd-b8c5-72a0828d7ea1'::uuid, timestamp '2026-11-08 21:00'),
('db352c48-e50c-4e2f-9d13-21870c75a1fc'::uuid, timestamp '2026-11-10 11:30')
